        Initialize NumberWordFormatter object.
        """
        self.NUMBER = ["", "ONE", "TWO", "THREE", "FOUR", "FIVE", "SIX", "SEVEN", "EIGHT", "NINE"]
        self.NUMBER_TEEN = ["TEN", "ELEVEN", "TWELVE", "THIRTEEN", "FOURTEEN", "FIFTEEN", "SIXTEEN", "SEVENTEEN",
                            "EIGHTEEN",
                            "NINETEEN"]
        self.NUMBER_TEN = ["TEN", "TWENTY", "THIRTY", "FORTY", "FIFTY", "SIXTY", "SEVENTY", "EIGHTY", "NINETY"]
        self.NUMBER_MORE = ["", "THOUSAND", "MILLION", "BILLION"]
        self.NUMBER_SUFFIX = ["k", "w", "", "m", "", "", "b", "", "", "t", "", "", "p", "", "", "e"]

    def format(self, x):
        """
        Converts a number into words format
        :param x: int or float, the number to be converted into words format
        :return: str, the number in words format
        >>> formatter = NumberWordFormatter()
        >>> formatter.format(123456)
        "ONE HUNDRED AND TWENTY THREE THOUSAND FOUR HUNDRED AND FIFTY SIX ONLY"
        """
        if x is None:
            return ""
        if isinstance(x, str):
            try:
                x = float(x) if '.' in x else int(x)
            except Exception:
                return ""
        if isinstance(x, float):
            int_part = int(x)
            dec_part = str(x).split(".")[1]
            words = self._format_int(int_part)
            if dec_part and int(dec_part) != 0:
                dec_words = self._format_decimal(dec_part)
                return f"{words} POINT {dec_words} ONLY"
            else:
                return f"{words} ONLY"
        elif isinstance(x, int):
            return f"{self._format_int(x)} ONLY"
        else:
            return ""

    def format_string(self, x):
        """
        Converts a string representation of a number into words format
        :param x: str, the string representation of a number
        :return: str, the number in words format
        >>> formatter = NumberWordFormatter()
        >>> formatter.format_string("123456")
        "ONE HUNDRED AND TWENTY THREE THOUSAND FOUR HUNDRED AND FIFTY SIX ONLY"
        """
        if x is None or x.strip() == "":
            return ""
        try:
            if '.' in x:
                num = float(x)
            else:
                num = int(x)
        except Exception:
            return ""
        return self.format(num)

    def trans_two(self, s):
        """
        Converts a two-digit number into words format
        :param s: str, the two-digit number
        :return: str, the number in words format
        >>> formatter = NumberWordFormatter()
        >>> formatter.trans_two("23")
        "TWENTY THREE"
        """
        if s is None or s.strip() == "":
            return ""
        s = s.zfill(2)
        if not s.isdigit():
            return ""
        n = int(s)
        if n == 0:
            return ""
        if n < 10:
            return self.NUMBER[n]
        elif 10 <= n < 20:
            return self.NUMBER_TEEN[n - 10]
        else:
            ten = int(s[0])
            unit = int(s[1])
            ten_word = self.NUMBER_TEN[ten - 1] if ten > 0 else ""
            unit_word = self.NUMBER[unit] if unit > 0 else ""
            if unit_word:
                return f"{ten_word} {unit_word}".strip()
            else:
                return ten_word

    def trans_three(self, s):
        """
        Converts a three-digit number into words format
        :param s: str, the three-digit number
        :return: str, the number in words format
        >>> formatter = NumberWordFormatter()
        >>> formatter.trans_three("123")
        "ONE HUNDRED AND TWENTY THREE"
        """
        if s is None or s.strip() == "":
            return ""
        s = s.zfill(3)
        if not s.isdigit():
            return ""
        n = int(s)
        if n == 0:
            return ""
        hundred = int(s[0])
        rest = s[1:]
        words = []
        if hundred > 0:
            words.append(f"{self.NUMBER[hundred]} HUNDRED")
            if int(rest) > 0:
                words.append("AND")
        if int(rest) > 0:
            words.append(self.trans_two(rest))
        return " ".join(words).strip()

    def parse_more(self, i):
        """
        Parses the thousand/million/billion suffix based on the index
        :param i: int, the index representing the magnitude (thousand, million, billion)
        :return: str, the corresponding suffix for the magnitude
        >>> formatter = NumberWordFormatter()
        >>> formatter.parse_more(1)
        "THOUSAND"
        """
        if i < 0 or i >= len(self.NUMBER_MORE):
            return ""
        return self.NUMBER_MORE[i]

    # --- Internal helpers ---

    def _format_int(self, n):
        if n == 0:
            return "ZERO"
        s = str(n)
        groups = []
        while s:
            groups.insert(0, s[-3:])
            s = s[:-3]
        words = []
        for idx, grp in enumerate(groups):
            grp_int = int(grp)
            if grp_int == 0:
                continue
            grp_words = self.trans_three(grp)
            more_idx = len(groups) - idx - 1
            more_word = self.parse_more(more_idx)
            if more_word:
                words.append(f"{grp_words} {more_word}".strip())
            else:
                words.append(grp_words)
        return " ".join(words).strip()

    def _format_decimal(self, dec_part):
        dec_words = []
        for digit in dec_part:
            if digit.isdigit():
                dec_words.append(self.NUMBER[int(digit)])
        return " ".join(dec_words).strip()

import re

class NumericEntityUnescaper:
    """
    This is a class that provides functionality to replace numeric entities with their corresponding characters in a given string.
    """

    def __init__(self):
        pass

    def replace(self, string):
        """
        Replaces numeric character references (HTML entities) in the input string with their corresponding Unicode characters.
        :param string: str, the input string containing numeric character references.
        :return: str, the input string with numeric character references replaced with their corresponding Unicode characters.
        >>> unescaper = NumericEntityUnescaper()
        >>> unescaper.replace("&#65;&#66;&#67;")
        'ABC'

        """
        if not isinstance(string, str) or not string:
            return "" if string == "" else string

        # Pattern matches: &#65; or &#x41; or &#X41;
        def entity_replacer(match):
            entity = match.group(0)
            # Remove leading '&#' and trailing ';'
            inner = entity[2:-1]
            if inner.startswith(('x', 'X')):
                # Hexadecimal
                num_str = inner[1:]
                try:
                    codepoint = int(num_str, 16)
                except ValueError:
                    return entity  # Leave unchanged if invalid
            else:
                # Decimal
                try:
                    codepoint = int(inner, 10)
                except ValueError:
                    return entity  # Leave unchanged if invalid
            try:
                return chr(codepoint)
            except (ValueError, OverflowError):
                return entity  # Leave unchanged if invalid codepoint

        pattern = re.compile(r'&#[xX]?[0-9a-fA-F]+;')
        return pattern.sub(entity_replacer, string)

    @staticmethod
    def is_hex_char(char):
        """
        Determines whether a given character is a hexadecimal digit.
        :param char: str, the character to check.
        :return: bool, True if the character is a hexadecimal digit, False otherwise.
        >>> NumericEntityUnescaper.is_hex_char('a')
        True

        """
        if not isinstance(char, str) or len(char) != 1:
            return False
        return char.lower() in '0123456789abcdef'

