        # Safe evaluation using AST
        try:
            node = ast.parse(expression, mode='eval')
            allowed_operators = {
                ast.Add: operator.add,
                ast.Sub: operator.sub,
                ast.Mult: operator.mul,
                ast.Div: operator.truediv,
                ast.Pow: operator.pow,
                ast.USub: operator.neg,
                ast.UAdd: operator.pos,
            }

            def eval_node(n):
                if isinstance(n, ast.Expression):
                    return eval_node(n.body)
                elif isinstance(n, ast.BinOp):
                    left = eval_node(n.left)
                    right = eval_node(n.right)
                    op_type = type(n.op)
                    if op_type in allowed_operators:
                        return allowed_operators[op_type](left, right)
                    else:
                        raise ValueError("Unsupported operator")
                elif isinstance(n, ast.UnaryOp):
                    operand = eval_node(n.operand)
                    op_type = type(n.op)
                    if op_type in allowed_operators:
                        return allowed_operators[op_type](operand)
                    else:
                        raise ValueError("Unsupported unary operator")
                elif isinstance(n, ast.Constant):
                    if isinstance(n.value, (int, float)):
                        return n.value
                    else:
                        raise ValueError("Unsupported constant")
                elif isinstance(n, ast.Num):  # For older Python versions
                    return n.n
                else:
                    raise ValueError("Unsupported expression")

            result = eval_node(node)
            # Accept small floating point errors
            return abs(result - 24) < 1e-6
        except Exception:
            return False

class Words2Numbers:
    """
    The class provides a text-to-number conversion utility, allowing conversion of written numbers (in words) to their numerical representation.
    """

    def __init__(self):
        """
        Initialize the word lists and dictionaries required for conversion
        """
        self.numwords = {}
        self.units = [
            "zero", "one", "two", "three", "four", "five", "six", "seven", "eight",
            "nine", "ten", "eleven", "twelve", "thirteen", "fourteen", "fifteen",
            "sixteen", "seventeen", "eighteen", "nineteen",
        ]
        self.tens = ["", "", "twenty", "thirty", "forty", "fifty", "sixty", "seventy", "eighty", "ninety"]
        self.scales = ["hundred", "thousand", "million", "billion", "trillion"]

        self.numwords["and"] = (1, 0)
        for idx, word in enumerate(self.units):
            self.numwords[word] = (1, idx)
        for idx, word in enumerate(self.tens):
            if word:  # skip empty strings for 0, 1
                self.numwords[word] = (1, idx * 10)
        for idx, word in enumerate(self.scales):
            self.numwords[word] = (10 ** (idx * 3 or 2), 0)

        self.ordinal_words = {'first': 1, 'second': 2, 'third': 3, 'fifth': 5, 'eighth': 8, 'ninth': 9, 'twelfth': 12}
        self.ordinal_endings = [('ieth', 'y'), ('th', '')]

    def text2int(self, textnum):
        """
        Convert the word string to the corresponding integer string
        :param textnum: string, the word string to be converted
        :return: string, the final converted integer string
        >>> w2n = Words2Numbers()
        >>> w2n.text2int("thirty-two")
        "32"
        """
        if textnum is None:
            raise ValueError("Input cannot be None")
        if not isinstance(textnum, str):
            raise ValueError("Input must be a string")
        textnum = textnum.lower().replace("-", " ")
        current = result = 0
        tokens = textnum.split()
        if not tokens:
            raise ValueError("Input string is empty")
        for idx, word in enumerate(tokens):
            if word in self.ordinal_words:
                scale = 1
                increment = self.ordinal_words[word]
            else:
                for ending, replacement in self.ordinal_endings:
                    if word.endswith(ending):
                        base = word[:-len(ending)] + replacement
                        if base in self.numwords:
                            word = base
                        break
                if word not in self.numwords:
                    raise ValueError(f"Illegal word: {word}")
                scale, increment = self.numwords[word]

            if scale > 1:
                current = max(1, current)
                current *= scale
            else:
                current += increment

            if scale > 100:
                result += current
                current = 0

        total = result + current
        return str(total)

    def is_valid_input(self, textnum):
        """
        Check if the input text contains only valid words that can be converted into numbers.
        :param textnum: The input text containing words representing numbers.
        :return: True if input is valid, False otherwise.
        >>> w2n = Words2Numbers()
        >>> w2n.is_valid_input("thirty-two")
        False
        """
        if textnum is None or not isinstance(textnum, str):
            return False
        textnum = textnum.lower().replace("-", " ")
        tokens = textnum.split()
        if not tokens:
            return False
        for word in tokens:
            if word in self.ordinal_words:
                continue
            valid = False
            for ending, replacement in self.ordinal_endings:
                if word.endswith(ending):
                    base = word[:-len(ending)] + replacement
                    if base in self.numwords:
                        valid = True
                        break
            if valid:
                continue
            if word not in self.numwords:
                return False
        return True
